'use strict';
(()=>{
 const panel=document.createElement('dialog');panel.id='guide-picker';panel.setAttribute('aria-labelledby','guide-picker-title');document.body.append(panel);
 const triggers=new Map();let active=null;
 function refresh(select){triggers.get(select)?.querySelector('span').replaceChildren(document.createTextNode(select.selectedOptions[0]?.textContent||''));}
 function close(){panel.close();if(active){triggers.get(active).setAttribute('aria-expanded','false');triggers.get(active).focus({preventScroll:true});}}
 function open(select){active=select;panel.replaceChildren();const header=document.createElement('header'),title=document.createElement('h2'),dismiss=document.createElement('button');title.id='guide-picker-title';title.textContent=document.querySelector(`label[for="${select.id}"]`).textContent;dismiss.textContent='×';dismiss.setAttribute('aria-label','关闭选择面板');dismiss.onclick=close;header.append(title,dismiss);panel.append(header);const list=document.createElement('div');list.className='guide-picker-options';list.setAttribute('role','listbox');list.setAttribute('aria-label',title.textContent);for(const option of select.options){const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.setAttribute('aria-selected',String(option.selected));button.dataset.value=option.value;if(select.id==='role'){const img=document.createElement('img');img.src=`/static/closet-app/assets/care-portraits/${option.value}-closeup.png`;img.alt='';button.append(img)}const label=document.createElement('span');label.textContent=option.textContent;const check=document.createElement('span');check.textContent=option.selected?'✓':'';check.setAttribute('aria-hidden','true');button.append(label,check);button.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));refresh(select);close()};list.append(button)}panel.append(list);triggers.get(select).setAttribute('aria-expanded','true');panel.showModal();list.querySelector('[aria-selected="true"]')?.focus({preventScroll:true});}
 for(const select of document.querySelectorAll('.studio select')){select.hidden=true;select.tabIndex=-1;const button=document.createElement('button');button.type='button';button.className='guide-selector';button.dataset.select=select.id;button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label',document.querySelector(`label[for="${select.id}"]`).textContent);button.innerHTML='<span></span><b aria-hidden="true">⌄</b>';select.after(button);triggers.set(select,button);refresh(select);button.onclick=()=>open(select);select.addEventListener('change',()=>refresh(select));}
 panel.addEventListener('cancel',e=>{e.preventDefault();close()});panel.addEventListener('click',e=>{if(e.target===panel)close()});panel.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const options=[...panel.querySelectorAll('[role=option]')],i=options.indexOf(document.activeElement);options[e.key==='Home'?0:e.key==='End'?options.length-1:Math.max(0,Math.min(options.length-1,i+(e.key==='ArrowDown'?1:-1)))].focus()});
})();
